{/* */}
  // Pies
{/* */}
  // Pareto
  const pareto = useMemo(() => { const re = fsFd.filter(r => r[1] === "Reales" && OC_ALL.includes(fsNormPL(r[0])) && ytdM.includes(r[3])); const map = {}; re.forEach(r => { const p=String(r[8]??"").trim(); const c=String(r[7]??"").trim(); if(!p||p==="--"||p==="—"||p==="- - -"||p==="NOAP"||p==="VARIOS"||!c||c==="--"||c==="—"||c==="- - -") return; if (!map[p]) map[p] = { t: 0, items: {} }; map[p].t += r[9]; if (!map[p].items[c]) map[p].items[c] = 0; map[p].items[c] += r[9] }); const arr = Object.entries(map).map(([k, v]) => ({ partner: k, total: v.t, items: v.items })).sort((a, b) => Math.abs(b.total) - Math.abs(a.total)); const grand = arr.reduce((s, x) => s + Math.abs(x.total), 0); let cum = 0; return arr.map(x => { cum += Math.abs(x.total); return { ...x, cumPct: grand ? cum / grand : 0 } }); }, [fsFd, cm]);
  const paretoMes = useMemo(() => { const re = fsFd.filter(r => r[1] === "Reales" && OC_ALL.includes(fsNormPL(r[0])) && r[3] === cm); const map = {}; re.forEach(r => { const p=String(r[8]??"").trim(); const c=String(r[7]??"").trim(); if(!p||p==="--"||p==="—"||p==="- - -"||p==="NOAP"||p==="VARIOS"||!c||c==="--"||c==="—"||c==="- - -") return; if (!map[p]) map[p] = { t: 0, items: {} }; map[p].t += r[9]; if (!map[p].items[c]) map[p].items[c] = 0; map[p].items[c] += r[9] }); const arr = Object.entries(map).map(([k, v]) => ({ partner: k, total: v.t, items: v.items })).sort((a, b) => Math.abs(b.total) - Math.abs(a.total)); const grand = arr.reduce((s, x) => s + Math.abs(x.total), 0); let cum = 0; return arr.map(x => { cum += Math.abs(x.total); return { ...x, cumPct: grand ? cum / grand : 0 } }); }, [fsFd, cm]);
  const maxPMes = paretoMes.length ? Math.abs(paretoMes[0].total) : 1;
{/* */}
{/* */}
  const toggleP = k => setExpP(p => ({ ...p, [k]: !p[k] }));
{/* */}
{/* */}
  const maxP = pareto.length ? Math.abs(pareto[0].total) : 1;
  const sel = { padding: "5px 10px", borderRadius: 6, border: "1px solid #D0D5E8", fontSize: 11, fontFamily: "inherit", background: "#fff", cursor: "pointer", color: "#1a1a2e" };
  const th = { fontSize: 9, color: "#8A90A8", fontWeight: 400, padding: "5px 6px", borderBottom: "1px solid #E4E8F2", whiteSpace: "nowrap" };
  const td = { fontSize: 10, padding: "5px 6px", borderBottom: "1px solid #f0f2fa" };
  const vc = v => v < 0 ? "#E24B4A" : v > 0 ? "#1D9E75" : "#ccc";
  const fv = (v, isPct, k) => isPct ? P(v) : INTEGER_KEYS.has(k) ? Math.round(v || 0).toLocaleString("en-US") : F(v);
  const renderLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent }) => { if (percent < 0.05) return null; const r = innerRadius + (outerRadius - innerRadius) * 0.5; const x = cx + r * Math.cos(-midAngle * Math.PI / 180); const y = cy + r * Math.sin(-midAngle * Math.PI / 180); return <text x={x} y={y} fill="#fff" textAnchor="middle" dominantBaseline="central" fontSize={9} fontWeight={500}>{`${(percent * 100).toFixed(0)}%`}</text> };
{/* */}
{/* */}
{/* */}
{/* */}
{/* */}
{/* */}
  // ═══ AREA × MONTH TABLE ═══
  const areaTable = useMemo(() => {
    const realOpex = fsFd.filter(r => r[1] === "Reales" && OC_ALL.includes(fsNormPL(r[0])) && ytdM.includes(r[3]));
    // Agrupar directamente por Molécula (sin nivel de Área Terapéutica)
    const molMap = {};
    realOpex.forEach(r => {
      const mol = mapMol(r[4]);
      if (!molMap[mol]) molMap[mol] = { monthly: {}, total: 0, cls: {} };
      ytdM.forEach(m => { if (!molMap[mol].monthly[m]) molMap[mol].monthly[m] = 0; });
      molMap[mol].monthly[r[3]] = (molMap[mol].monthly[r[3]] || 0) + r[9];
      molMap[mol].total += r[9];
      // Sub-group by Clasificación
      const cls = r[0] === "GP0001" ? (r[6] && r[6] !== "--" ? r[6] : "Operations") : (r[6] || "—");
      if (!molMap[mol].cls[cls]) molMap[mol].cls[cls] = { monthly: {}, total: 0 };
      ytdM.forEach(m => { if (!molMap[mol].cls[cls].monthly[m]) molMap[mol].cls[cls].monthly[m] = 0; });
      molMap[mol].cls[cls].monthly[r[3]] = (molMap[mol].cls[cls].monthly[r[3]] || 0) + r[9];
      molMap[mol].cls[cls].total += r[9];
    });
    return Object.entries(molMap)
      .map(([mol, data]) => ({ mol, ...data }))
      .sort((a, b) => Math.abs(b.total) - Math.abs(a.total));
  }, [fsFd, ytdM]);
  // Pie charts derived from areaTable - exact same source as the molecule table
  const pieYTD = useMemo(
    () => areaTable.map(row => ({ name: row.mol, value: Math.round(Math.abs(row.total)) })).filter(d => d.value > 0).sort((a, b) => b.value - a.value),
    [areaTable]
  );
  const pieCM = useMemo(
    () => areaTable.map(row => ({ name: row.mol, value: Math.round(Math.abs(row.monthly[cm] || 0)) })).filter(d => d.value > 0).sort((a, b) => b.value - a.value),
    [areaTable, cm]
  );
  const toggleArea = k => setExpArea(p => ({ ...p, [k]: !p[k] }));
{/* */}
