        const isForecastAtCutoff = r => r[2] > CUR_YEAR || (r[2] === CUR_YEAR && r[3] > cm);
        const isSelectedOriginAtCutoff = r => (isActualAtCutoff(r) && r[1] === "Reales") || (isForecastAtCutoff(r) && r[1] === "Forecast");
