        const shareBox = (title,obj) => { const entries=Object.entries(obj).sort((a,b)=>b[1]-a[1]).slice(0,5); const total=entries.reduce((s,e)=>s+e[1],0)||1; let acc=0; const bg=entries.map((e,i)=>{const p=e[1]/total*100; const seg=`${colors[i%colors.length]} ${acc}% ${acc+p}%`; acc+=p; return seg;}).join(','); return <div style={{background:'#fff',border:'1px solid #E4E8F2',borderRadius:18,padding:16}}><div style={{fontSize:13,fontWeight:800,marginBottom:8}}>{title}</div><div style={{width:130,height:130,borderRadius:'50%',margin:'8px auto',background:`conic-gradient(${bg})`,position:'relative'}}><div style={{position:'absolute',inset:34,background:'#fff',borderRadius:'50%'}} /></div>{entries.map((e,i)=><div key={e[0]} title={`${e[0]}: ${e[1]} molecule${e[1]===1?'':'s'} · ${Math.round(e[1]/total*100)}%`} style={{display:'flex',justifyContent:'space-between',fontSize:11,margin:'5px 0'}}><span><span style={{display:'inline-block',width:9,height:9,borderRadius:9,background:colors[i%colors.length],marginRight:6}} />{e[0]}</span><b>{Math.round(e[1]/total*100)}%</b></div>)}</div> };
