                    {cardOpen&&(()=>{const meta=metaForMol(x.raw),launch=launchOf(x);const get=(keys,fallback='--')=>inputValue(x,keys)||fallback;const release=get(['Release Date','Release_Date'],'')||(launch?`${MO[launch.m-1]} ${launch.y}`:'--');const fields=[['Molecule',x.mol],['Brand Name',get(['Brand Name'])],['Type',get(['Type','Type:'])],['Therapeutic Area',areaOf(x)],['Partner',partnerOfCard(x)],['Registration Number',get(['Registration Number'])],['Product Status',get(['Product Status'],meta.status||'Sin estatus')],['Partner Status',get(['Partner Status'])],['Regulatory Status',get(['Regulatory Status'])],['Link to Contract',get(['Link to Contract'])],['Release Date',release],['Units',get(['Units'])],['Channel',channelOf(x)],['Import Type',get(['Import Type'])],['Players',get(['Players'])],['Subjugations',get(['Subjugations','Subjugaciones'])],['Reference Price',get(['Reference Price'])],['Discount Price',get(['Discount Price'])],['Gross to Net',get(['Gross to Net'])],['Discount to Distributor',get(['Discount to Distributor','Discount to Distibuitor'])],['Other Discounts',get(['Other Discounts'])],['Supply Cost',get(['Supply Cost'])],['NSP%',get(['NSP%'])],['License Fee',get(['License Fee'])],['Royalty',get(['Royalty'])],['Market Share',get(['Market Share'])],['Sales Rep.',get(['Sales Rep.','Sales Rep'])],['Bioequivalence / Study of Fundamentals',get(['Bioequivalence / Study of Fundamentals'])],['MOQ',get(['MOQ'])],['Lead Time (Months)',get(['Lead Time (Months)','Lead Time'])],['Shelf Life',get(['Shelf Life'])],['Include IVA',get(['Include IVA'])],['Days to Collection',get(['Days to Collection'])],['Days to Pay',get(['Days to Pay'])],['Saya Price Retail',get(['Saya Price Retail'])],['Peak Sales',get(['Peak Sales'])],['EBITDA',get(['EBITDA'])],['NPV 11.51%',get(['NPV 11.51%','NPV'])],['TIR',get(['TIR','IRR'])]];return <div data-summary-card-detail-visible="true" style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:'8px 14px',fontSize:12,background:'#F8FAFC',borderRadius:14,padding:12,marginBottom:16}}>{fields.map(([label,value])=><React.Fragment key={label}><div style={{color:'#667085',fontWeight:900}}>{label}</div><div style={{fontWeight:800,textAlign:'right',wordBreak:'break-word'}}>{formatCardField(label,value)}</div></React.Fragment>)}</div>})()}
